}

package com.enterprise.banking;

import javax.ejb.Stateless;
import javax.ejb.TransactionAttribute;
import javax.ejb.TransactionAttributeType;
import javax.inject.Inject;
import java.math.BigDecimal;

@Stateless
public class TransferProcessingService {
    @Inject
    private AccountRepository accountRepository;
    @Inject
    private CicsMainframeGateway cicsGateway;

    @TransactionAttribute(TransactionAttributeType.REQUIRED)
    public String processTransfer(String fromAccountId, String toAccountId, BigDecimal amount) {
        if (amount == null || amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Amount must be positive");
        }
        Account from = accountRepository.findById(fromAccountId);
        Account to = accountRepository.findById(toAccountId);
        if (from == null || to == null) throw new IllegalArgumentException("Account not found");
        if (from.getBalance().compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");
        String correlationId = cicsGateway.executeTransfer(fromAccountId, toAccountId, amount);
        accountRepository.updateBalance(fromAccountId, from.getBalance().subtract(amount));
        accountRepository.updateBalance(toAccountId, to.getBalance().add(amount));
        return correlationId;
    }
}

