package com.legacy.banking.service;

import com.legacy.banking.domain.LoanApplication;
import com.legacy.banking.repository.LoanApplicationRepository;
import com.legacy.banking.gateway.CreditBureauGateway;
import javax.ejb.Stateless;
import javax.inject.Inject;
import java.math.BigDecimal;

@Stateless
public class LoanProcessingService {
    @Inject
    private LoanApplicationRepository loanRepository;
    @Inject
    private CreditBureauGateway creditGateway;

    public String submitApplication(String applicantId, BigDecimal amount) {
        int score = creditGateway.queryCreditScore(applicantId);
        if (score < 620) throw new IllegalStateException("Credit score threshold not met");
        LoanApplication app = new LoanApplication(applicantId, amount, "APPROVED");
        loanRepository.save(app);
        return app.getApplicationId();
    }
}

